<?php require __DIR__.'/includes/app.php';session_start_safe();$cid=(int)($_GET['cupo']??$_POST['cupo_id']??0);$q=db()->prepare("SELECT c.*,a.nombre actividad,a.estado,a.modo_control,a.fecha_apertura,a.fecha_cierre,co.nombre comision,t.hora_inicio,t.hora_fin FROM cupos c JOIN actividades a ON a.id=c.actividad_id JOIN comisiones co ON co.id=c.comision_id JOIN turnos t ON t.id=c.turno_id WHERE c.id=? AND c.habilitado=1 AND co.activa=1 AND t.activo=1");$q->execute([$cid]);$c=$q->fetch();if(!$c){http_response_code(404);exit('Cupo no encontrado');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_ok())$error='La sesión del formulario venció.';else{foreach(['familia','responsable','telefono'] as $f)if(trim($_POST[$f]??'')==='')$error='Completa los campos obligatorios.';if(!$error){try{$pdo=db();$pdo->beginTransaction();$lock=$pdo->prepare('SELECT capacidad FROM cupos WHERE id=? FOR UPDATE');$lock->execute([$cid]);$cap=(int)$lock->fetchColumn();$cnt=$pdo->prepare("SELECT COUNT(*) FROM inscripciones WHERE cupo_id=? AND estado='confirmada'");$cnt->execute([$cid]);[$st]=activity_state($c);if($st!=='abierta')throw new RuntimeException('La actividad no está abierta.');if((int)$cnt->fetchColumn()>=$cap)throw new RuntimeException('El turno acaba de completarse.');$du=$pdo->prepare("SELECT COUNT(*) FROM inscripciones WHERE actividad_id=? AND LOWER(familia)=LOWER(?) AND estado='confirmada'");$du->execute([$c['actividad_id'],trim($_POST['familia'])]);if((int)$du->fetchColumn()>0)throw new RuntimeException('Esta familia ya tiene una inscripción en la actividad.');$code=strtoupper(substr(bin2hex(random_bytes(6)),0,10));$ins=$pdo->prepare("INSERT INTO inscripciones(actividad_id,comision_id,turno_id,cupo_id,familia,responsable,telefono,estudiante,grado_seccion,observacion,codigo_confirmacion,ip_registro,navegador) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)");$ins->execute([$c['actividad_id'],$c['comision_id'],$c['turno_id'],$cid,trim($_POST['familia']),trim($_POST['responsable']),trim($_POST['telefono']),trim($_POST['estudiante']??''),trim($_POST['grado_seccion']??''),trim($_POST['observacion']??''),$code,substr($_SERVER['REMOTE_ADDR']??'',0,45),substr($_SERVER['HTTP_USER_AGENT']??'',0,255)]);$pdo->commit();go('confirmacion.php?codigo='.$code);}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$error=$e->getMessage();}}}}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registro</title><link rel="stylesheet" href="<?=e(url('assets/css/publico.css'))?>"></head><body><header class="hero"><div><h1>Registro de familia</h1><p><?=e($c['actividad'].' · '.$c['comision'].' · '.substr($c['hora_inicio'],0,5).'-'.substr($c['hora_fin'],0,5))?></p></div></header><main class="wrap"><section class="formcard"><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="cupo_id" value="<?=$cid?>"><?php foreach([['familia','Familia / apellidos *'],['responsable','Responsable *'],['telefono','Teléfono *'],['estudiante','Estudiante'],['grado_seccion','Grado y sección']] as [$n,$l]):?><div class="field"><label><?=e($l)?></label><input name="<?=e($n)?>" value="<?=e($_POST[$n]??'')?>" <?=$n==='familia'||$n==='responsable'||$n==='telefono'?'required':''?>></div><?php endforeach;?><div class="field"><label>Observación</label><textarea name="observacion" rows="3"><?=e($_POST['observacion']??'')?></textarea></div><button class="btn">Confirmar inscripción</button></form></section></main></body></html>
